const CACHE='retail-concept-v15';
const FILES=['./','index.html','styles.css?v=15','redesign.css?v=15','app.js?v=15','motion.js?v=15','motion.css?v=15','experience.css?v=15','flanders.js?v=15','assets/flanders-coupon.webp','favicon.svg','research.html','assets/taste-discovery.webp','assets/manrope-cyrillic.woff2','assets/manrope-latin.woff2','assets/gp.webp','assets/gw.webp','assets/gi.webp','assets/gd.webp','assets/gc.webp','assets/ib.webp','assets/is.webp','assets/iw.webp'];
self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES)).then(()=>self.skipWaiting())));
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('retail-concept-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',e=>{const url=new URL(e.request.url);if(e.request.method!=='GET'||url.origin!==self.location.origin)return;const request=e.request;const network=()=>fetch(request).then(r=>{if(r.ok){const copy=r.clone();e.waitUntil(caches.open(CACHE).then(c=>c.put(request,copy)));}return r;});if(/\.(woff2|webp|svg)$/.test(url.pathname)){e.respondWith(caches.match(request).then(hit=>hit||network()));return;}e.respondWith(network().catch(()=>caches.match(request).then(hit=>hit||(request.mode==='navigate'?caches.match('index.html'):Response.error()))));});
